-- name: platform__configuration_changeconnection_insert_integration_connections_ref_definition_key_state :one
INSERT INTO control_plane.integration_connections(ref,organization_id,definition_key,name,state,enabled,credential_materialization_ref,masked_credentials_state,public_configuration,created_by) SELECT $1,$2::uuid,d.stable_key,$3,'NOT_CONNECTED',true,$4,'NOT_CONFIGURED',$5,$6::uuid FROM control_plane.integration_definitions d WHERE d.stable_key=$7 AND d.enabled RETURNING ref,definition_key,name,state,masked_credentials_state,enabled,version,public_configuration,created_at,updated_at
